/**
 * **useAppLogic**
 * 
 * The central aggregation hook ("The Brain") for the entire CAD/CAM application.
 * It follows the "Container/Presenter" pattern where this hook acts as the Container logic
 * for the root `App` component.
 * 
 * **Responsibilities:**
 * 1.  Aggregates sub-hooks (`persistence`, `editor`, `nesting`, `ui`, `simulation`).
 * 2.  Manages high-level `AppMode` switching.
 * 3.  Defines complex event handlers that cross domain boundaries (e.g., File Upload affecting Editor, Nesting affecting Simulation).
 * 4.  Calculates derived state used by multiple child components.
 * 
 * **Usage:**
 * ```tsx
 * const App = () => {
 *   const logic = useAppLogic();
 *   return <AppUI {...logic} />;
 * }
 * ```
 * 
 * @returns {UseAppLogicResult} An object containing all state selectors and action dispatchers required by the UI.
 */
export const useAppLogic = (): UseAppLogicResult => {
    const [mode, setMode] = useState<AppMode>(AppMode.PartEditor);

    // --- 1. Состояние данных (Persistence) ---
    const persistence = useAppPersistence();

    // --- 2. Состояние интерфейса ---
    const ui = useUIState();
    const { confirmationState, confirm, closeConfirmation } = useConfirmation();

    // --- 3. Состояние редактора ---
    const editor = useEditorState({ 
        tools: persistence.tools, 
        onAddPunches: (data) => {
            // Note: We use a callback pattern here to ensure we work with the latest state
            // inside the editor hook's own state management if possible, but here we perform the logic
            editor.setActivePart(currentPart => {
                if (currentPart) {
                    const newPunches = data.map(p => ({ ...p, id: generateId() }));
                    return { ...currentPart, punches: [...currentPart.punches, ...newPunches] };
                }
                return null;
            });
        }
    });

    // --- 4. Состояние раскроя ---
    const nesting = useNestingState(persistence.nests[0]?.id || null);
    const activeNest = useMemo(() => persistence.nests.find(n => n.id === nesting.activeNestId) || null, [persistence.nests, nesting.activeNestId]);
    const currentNestSheet = useMemo(() => activeNest?.sheets[nesting.activeSheetIndex] || null, [activeNest, nesting.activeSheetIndex]);

    // --- 5. Состояние симуляции ---
    const simulation = useSimulationState();

    // --- 6. Импорт файлов ---
    const { handleFileUpload } = useFileImport({ 
        tools: persistence.tools, setMode, setActivePart: editor.setActivePart, addToast: ui.addToast 
    });

    // --- 7. Навигация и Pan/Zoom ---
    const handleCanvasClickProxy = useCallback((rawPoint: Point) => {
        if (mode === AppMode.Nesting) return;
        if (mode !== AppMode.PartEditor || !editor.activePart) return;

        const point = { x: rawPoint.x, y: -rawPoint.y };

        if (editor.teachMode) {
             const closestSeg = findClosestSegment(point, editor.activePartProcessedGeometry);
             if (closestSeg) {
                 const idx = editor.activePartProcessedGeometry?.segments.findIndex((s: any) => 
                     Math.abs(s.p1.x - closestSeg.p1.x) < 0.001 && Math.abs(s.p1.y - closestSeg.p1.y) < 0.001 &&
                     Math.abs(s.p2.x - closestSeg.p2.x) < 0.001 && Math.abs(s.p2.y - closestSeg.p2.y) < 0.001
                 ) ?? -1;

                 if (idx !== -1) {
                     editor.setSelectedSegmentIds(prev => prev.includes(idx) ? prev.filter(i => i !== idx) : [...prev, idx]);
                 }
             }
             return;
        }

        if (editor.selectedPunchId) editor.setSelectedPunchId(null);
        editor.manualPunch.handleCanvasClick(rawPoint);
    }, [mode, editor.activePart, editor.teachMode, editor.activePartProcessedGeometry, editor.selectedPunchId, editor.manualPunch]);

    const panZoom = usePanAndZoom({ x: 0, y: 0, width: 100, height: 100 }, { onClick: handleCanvasClickProxy });

    // --- Side Effects ---
    useEffect(() => {
        simulation.setOptimizedOperations(null);
        simulation.setSimulationStep(0);
        simulation.setIsSimulating(false);
    }, [nesting.activeNestId, nesting.activeSheetIndex, currentNestSheet]);

    useEffect(() => {
        if (editor.activePart) {
            panZoom.setViewBox({ x: -5, y: -editor.activePart.geometry.height - 5, width: editor.activePart.geometry.width + 10, height: editor.activePart.geometry.height + 10 });
            editor.setSelectedPunchId(null);
        }
    }, [editor.activePart?.id]); 

    useEffect(() => {
        editor.setSelectedPunchId(null);
        editor.setTeachMode(false);
        if (mode === AppMode.Nesting && activeNest) {
             const sheetToView = activeNest.sheets[nesting.activeSheetIndex];
             let width = 2500, height = 1250;
             if (sheetToView) { width = sheetToView.width; height = sheetToView.height; }
             else { 
                const stock = activeNest.settings.availableSheets.find(s => s.id === activeNest.settings.activeSheetId) || activeNest.settings.availableSheets[0]; 
                if(stock) { width = stock.width; height = stock.height; } 
             }
             panZoom.setViewBox({ x: -50, y: -height - 50, width: width + 100, height: height + 100 });
        }
    }, [mode, nesting.activeNestId, nesting.activeSheetIndex]);

    // --- Business Handlers ---
    const onRunOptimization = (finalSettings: OptimizerSettings) => {
        if (!currentNestSheet) return;
        persistence.setOptimizerSettings(finalSettings);
        ui.setShowOptimizerModal(false);

        const ops = calculateOptimizedPath(currentNestSheet, persistence.parts, persistence.tools, finalSettings);
        simulation.setOptimizedOperations(ops);
        simulation.setSimulationStep(0); 

        if (ui.isGeneratingGCode) {
            const programNumber = nesting.activeSheetIndex + 1;
            const ncFilename = activeNest?.workOrder ? `${activeNest.workOrder}_${programNumber}.nc` : `Program_${programNumber}.nc`;
            const code = generateGCode(currentNestSheet, persistence.parts, persistence.tools, ncFilename, persistence.machineSettings, finalSettings, activeNest?.settings.clampPositions, programNumber, ops);
            ui.setGeneratedGCode(code);
            ui.setShowGCodeModal(true);
        } else {
            ui.addToast(`Оптимизация завершена. ${ops.length} операций.`, "success");
        }
    };

    const handleRunNesting = async () => {
        if(!activeNest || activeNest.scheduledParts.length===0) return;
        nesting.setIsNestingProcessing(true);
        nesting.setNestingProgress(0);
        nesting.setNestingStatus('Инициализация...');
        persistence.setNests(n => n.map(x => x.id === nesting.activeNestId ? {...x, sheets: []} : x)); 
        nesting.setActiveSheetIndex(0);

        try {
            for await (const update of nestingGenerator(activeNest.scheduledParts, persistence.parts, persistence.tools, activeNest.settings)) {
                persistence.setNests(prev => prev.map(n => n.id === nesting.activeNestId ? { ...n, sheets: update.sheets } : n));
                nesting.setNestingProgress(update.progress);
                nesting.setNestingStatus(update.status);
            }
            ui.addToast("Раскрой завершен", "success");
        } catch(e) {
            const errorMsg = e instanceof Error ? e.message : String(e);
            ui.addToast("Ошибка раскроя: " + errorMsg, "error");
        } finally {
            nesting.setIsNestingProcessing(false);
        }
    };

    const downloadGCode = () => {
        const blob = new Blob([ui.generatedGCode], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = activeNest?.workOrder ? `${activeNest.workOrder}_${nesting.activeSheetIndex + 1}.nc` : `Program_${nesting.activeSheetIndex + 1}.nc`;
        document.body.appendChild(link); link.click(); document.body.removeChild(link); URL.revokeObjectURL(url);
    };

    return {
        mode, setMode,
        persistence,
        ui,
        editor,
        nesting,
        simulation,
        confirmation: { state: confirmationState, confirm, close: closeConfirmation },
        panZoom,
        handlers: {
            onRunOptimization,
            handleRunNesting,
            handleFileUpload,
            downloadGCode,
            onGenerateGCodeRequest: () => { if(!currentNestSheet) { ui.addToast("Нет листа", "error"); return; } ui.setIsGeneratingGCode(true); ui.setShowOptimizerModal(true); },
            onOptimizePathRequest: () => { if(!currentNestSheet) { ui.addToast("Нет листа", "error"); return; } ui.setIsGeneratingGCode(false); ui.setShowOptimizerModal(true); },
            onClearAllPunches: () => confirm("Очистка", "Удалить все инструменты?", () => { editor.setActivePart(p => p ? {...p, punches: []} : null); ui.addToast("Инструменты удалены", "info"); }),
            onAutoPunchApply: (s: AutoPunchSettings) => { 
                const p = generateContourPunches(editor.activePart!.geometry, persistence.tools, s, persistence.turretLayouts, persistence.teachCycles); 
                if (editor.activePart) { 
                    const newPunches = p.map(px => ({...px, id: generateId()})); 
                    editor.setActivePart(prev => prev ? {...prev, punches: [...prev.punches, ...newPunches]} : null); 
                } 
                ui.setShowAutoPunchSettingsModal(false); 
                ui.addToast(`Сгенерировано: ${p.length}`, "success"); 
            },
            onSaveTeachCycle: (name: string, symmetry: any) => {
                const cycle = createTeachCycleFromSelection(name, symmetry, editor.selectedSegmentIds, editor.selectedTeachPunchIds, editor.activePart!, editor.activePartProcessedGeometry!);
                if (cycle) { persistence.setTeachCycles(prev => [...prev, cycle]); editor.setTeachMode(false); }
                ui.setShowTeachSaveModal(false);
            }
        },
        derived: {
            activeNest,
            currentNestSheet
        }
    };
};

/**
 * ГЛАВНЫЙ ХУК РЕДАКТОРА (Агрегатор)
 * Объединяет специализированные хуки состояния и подключает логику ручной пробивки.
 * Сохраняет интерфейс для useAppLogic.
 */
import React from 'react';
import { Tool, PlacedTool, Part, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings } from '../types';
import { useActivePartState } from './editor/useActivePartState';
import { usePunchToolState } from './editor/usePunchToolState';
import { usePunchSettingsState } from './editor/usePunchSettingsState';
import { useTeachState } from './editor/useTeachState';
import { useManualPunch } from './useManualPunch';
import { ProcessedGeometry } from '../services/geometry';

interface UseEditorStateProps {
    tools: Tool[];
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
}

export interface UseEditorStateResult {
    activePart: Part | null;
    setActivePart: (part: Part | null | ((prev: Part | null) => Part | null)) => void;
    activePartProcessedGeometry: ProcessedGeometry | null;
    selectedToolId: string | null;
    setSelectedToolId: (id: string | null) => void;
    selectedPunchId: string | null;
    setSelectedPunchId: (id: string | null) => void;
    punchOrientation: number;
    setPunchOrientation: (angle: number) => void;
    snapMode: SnapMode;
    setSnapMode: (mode: SnapMode) => void;
    punchOffset: number;
    setPunchOffset: (offset: number) => void;
    selectedTool: Tool | null;
    manualPunchMode: ManualPunchMode;
    setManualPunchMode: (mode: ManualPunchMode) => void;
    nibbleSettings: NibbleSettings;
    setNibbleSettings: (settings: NibbleSettings) => void;
    destructSettings: DestructSettings;
    setDestructSettings: (settings: DestructSettings) => void;
    teachMode: boolean;
    setTeachMode: (val: boolean) => void;
    selectedSegmentIds: number[];
    setSelectedSegmentIds: React.Dispatch<React.SetStateAction<number[]>>;
    selectedTeachPunchIds: string[];
    setSelectedTeachPunchIds: React.Dispatch<React.SetStateAction<string[]>>;
    manualPunch: ReturnType<typeof useManualPunch>;
}

/**
 * **useEditorState**
 * 
 * Aggregates all state related to the single Part Editor view.
 * Splits responsibilities into sub-hooks (`useActivePartState`, `usePunchToolState`, etc.)
 * but exposes a unified API for the `App` component.
 * 
 * **Purpose:**
 * - Manages the `ActivePart` currently being edited.
 * - Tracks the selected Tool and Punch configuration (orientation, snap).
 * - Manages the specific `ManualPunchMode` (Single, Nibble, Destruct).
 * - Integrates the `useManualPunch` logic handler.
 * 
 * @param {UseEditorStateProps} props
 * @returns {UseEditorStateResult}
 */
export const useEditorState = ({ tools, onAddPunches }: UseEditorStateProps): UseEditorStateResult => {
    // 1. Распределенное состояние
    const part = useActivePartState();
    const tool = usePunchToolState(tools);
    const settings = usePunchSettingsState();
    const teach = useTeachState();

    // 2. Подключение логики кликов (Manual Punch)
    const manualPunch = useManualPunch({
        activePart: part.activePart,
        activePartProcessedGeometry: part.activePartProcessedGeometry,
        selectedTool: tool.selectedTool,
        manualPunchMode: settings.manualPunchMode,
        punchOrientation: tool.punchOrientation,
        punchOffset: tool.punchOffset,
        snapMode: tool.snapMode,
        nibbleSettings: settings.nibbleSettings,
        destructSettings: settings.destructSettings,
        onAddPunches,
        setSelectedPunchId: tool.setSelectedPunchId
    });

    // 3. Сборка единого объекта (Backward Compatibility)
    return {
        // Состояние детали
        activePart: part.activePart,
        setActivePart: part.setActivePart,
        activePartProcessedGeometry: part.activePartProcessedGeometry,

        // Состояние выбора инструмента
        selectedToolId: tool.selectedToolId,
        setSelectedToolId: tool.setSelectedToolId,
        selectedPunchId: tool.selectedPunchId,
        setSelectedPunchId: tool.setSelectedPunchId,
        punchOrientation: tool.punchOrientation,
        setPunchOrientation: tool.setPunchOrientation,
        snapMode: tool.snapMode,
        setSnapMode: tool.setSnapMode,
        punchOffset: tool.punchOffset,
        setPunchOffset: tool.setPunchOffset,
        selectedTool: tool.selectedTool,

        // Настройки режимов
        manualPunchMode: settings.manualPunchMode,
        setManualPunchMode: settings.setManualPunchMode,
        nibbleSettings: settings.nibbleSettings,
        setNibbleSettings: settings.setNibbleSettings,
        destructSettings: settings.destructSettings,
        setDestructSettings: settings.setDestructSettings,

        // Режим обучения
        teachMode: teach.teachMode,
        setTeachMode: teach.setTeachMode,
        selectedSegmentIds: teach.selectedSegmentIds,
        setSelectedSegmentIds: teach.setSelectedSegmentIds,
        selectedTeachPunchIds: teach.selectedTeachPunchIds,
        setSelectedTeachPunchIds: teach.setSelectedTeachPunchIds,

        // Интеграция логики
        manualPunch
    };
};

import { useMemo } from 'react';
import { Part, Tool, Point, ManualPunchMode, SnapMode, PlacementSide, ToolShape, NibbleSettings, PlacedTool } from '../types';
import { ProcessedGeometry, findClosestSegment, findSnapPoint, isPointInsideContour } from '../services/geometry';
import { calculateEdgePlacement } from '../services/placement';
import { generateNibblePunches } from '../services/punching';

interface UseGhostPreviewProps {
    mousePos: Point | null;
    activePart: Part | null;
    processedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | undefined;
    manualPunchMode: ManualPunchMode;
    snapMode: SnapMode;
    punchOrientation: number;
    punchOffset: number;
    nibbleSettings: NibbleSettings;
    punchCreationStep: number; // For Destruct mode hiding
    teachMode: boolean;
}

interface GhostPreviewResult {
    ghostPunches: { x: number, y: number, rotation: number }[];
    ghostLine: { x1: number, y1: number, x2: number, y2: number } | null;
    snapPoint: Point | null;
}

/**
 * **useGhostPreview**
 * 
 * Calculates the "Ghost" (preview) visual for the punch tool before the user clicks.
 * This provides real-time visual feedback on where the tool will be placed, 
 * factoring in snapping, rotation, and specific mode logic (Nibble/Punch).
 * 
 * **Behaviors:**
 * - **Punch Mode:** Shows a single tool outline snapped to vertices/edges or free-floating.
 * - **Nibble Mode:** Shows a series of tool outlines along the closest line segment.
 * - **Destruct Mode:** Hides preview during the first step of defining the rectangle.
 * - **Teach Mode:** Disables ghost preview.
 * 
 * **Edge Cases:**
 * - `mousePos` is null (cursor outside canvas) -> Returns empty result.
 * - `selectedTool` is undefined -> Returns empty result.
 * - Geometry processing errors -> Falls back to raw mouse position.
 * 
 * @param {UseGhostPreviewProps} props Inputs primarily from `useEditorState`.
 * @returns {GhostPreviewResult} Data structure for rendering ghost elements in the Canvas.
 */
export const useGhostPreview = ({
    mousePos,
    activePart,
    processedGeometry,
    selectedTool,
    manualPunchMode,
    snapMode,
    punchOrientation,
    punchOffset,
    nibbleSettings,
    punchCreationStep,
    teachMode
}: UseGhostPreviewProps): GhostPreviewResult => {

    return useMemo(() => {
        if (!mousePos || !selectedTool || !activePart || teachMode) {
            return { ghostPunches: [], ghostLine: null, snapPoint: null };
        }

        if (manualPunchMode === ManualPunchMode.Destruct && punchCreationStep === 1) {
            return { ghostPunches: [], ghostLine: null, snapPoint: null }; // handled by separate logic or hidden
        }

        if (manualPunchMode === ManualPunchMode.Nibble) {
            const closestSeg = findClosestSegment(mousePos, processedGeometry);
            if (closestSeg) {
                const segAngle = closestSeg.angle;
                const combinedRotation = segAngle + punchOrientation;

                let perpOffset = selectedTool.height / 2;
                if (Math.abs(punchOrientation % 180) > 45 && Math.abs(punchOrientation % 180) < 135) {
                    perpOffset = selectedTool.width / 2;
                    if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2;
                } else {
                    if (selectedTool.shape === ToolShape.Circle) perpOffset = selectedTool.width / 2;
                }

                const ux = Math.cos(segAngle * Math.PI / 180);
                const uy = Math.sin(segAngle * Math.PI / 180);
                const nx = -uy;
                const ny = ux;

                const midX = (closestSeg.p1.x + closestSeg.p2.x) / 2;
                const midY = (closestSeg.p1.y + closestSeg.p2.y) / 2;
                const testP = { x: midX + nx * perpOffset, y: midY + ny * perpOffset };

                let finalOffsetSign = 1;

                if (processedGeometry) {
                    const rawTestP = {
                        x: testP.x + processedGeometry.bbox.minX,
                        y: processedGeometry.bbox.minY + testP.y 
                    };
                    if (isPointInsideContour(rawTestP, activePart.geometry)) {
                        finalOffsetSign = -1; 
                    }
                }

                const previewPunches = generateNibblePunches(
                    closestSeg.p1, 
                    closestSeg.p2, 
                    selectedTool, 
                    nibbleSettings, 
                    closestSeg.angle, 
                    closestSeg.wasNormalized, 
                    combinedRotation, 
                    perpOffset * finalOffsetSign
                );

                return {
                    ghostPunches: previewPunches.map(p => ({ x: p.x, y: p.y, rotation: p.rotation })),
                    ghostLine: { x1: closestSeg.p1.x, y1: closestSeg.p1.y, x2: closestSeg.p2.x, y2: closestSeg.p2.y },
                    snapPoint: null
                };
            }
            return { ghostPunches: [], ghostLine: null, snapPoint: null };
        }

        if (manualPunchMode === ManualPunchMode.Punch) {
            const snapResult = findSnapPoint(mousePos, processedGeometry, snapMode);
            if (!snapResult && snapMode !== SnapMode.Off) return { ghostPunches: [], ghostLine: null, snapPoint: null };

            const placementPoint = snapResult?.point ?? mousePos;
            let finalPlacement: { x: number, y: number, rotation: number };

            const isShapeCenter = snapResult && snapMode === SnapMode.ShapeCenter;

            if (isShapeCenter) {
                let rotation = punchOrientation;
                if (snapResult?.forceRotation !== undefined) {
                    const holeAngle = snapResult.forceRotation;
                    const isToolHorizontal = selectedTool.width >= selectedTool.height;

                    if (isToolHorizontal) {
                        rotation = holeAngle;
                    } else {
                        rotation = (holeAngle + 90) % 360;
                    }
                }
                finalPlacement = { x: placementPoint.x, y: placementPoint.y, rotation };
            } else {
                const placementAngle = snapResult?.angle ?? 0;

                const placementA = calculateEdgePlacement(
                    placementPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Outside
                );
                const placementB = calculateEdgePlacement(
                    placementPoint, placementAngle, selectedTool, punchOrientation, punchOffset, 
                    snapResult?.snapTarget ?? 'middle', snapResult?.wasNormalized ?? false, PlacementSide.Inside
                );

                finalPlacement = placementA;

                if (processedGeometry && activePart) {
                    const isInsideA = isPointInsideContour(placementA, activePart.geometry);
                    const isInsideB = isPointInsideContour(placementB, activePart.geometry);

                    if (!isInsideA && isInsideB) {
                        finalPlacement = placementA;
                    } else if (isInsideA && !isInsideB) {
                        finalPlacement = placementB;
                    } else {
                        finalPlacement = placementA;
                    }
                }
            }

            return {
                ghostPunches: [finalPlacement],
                ghostLine: null,
                snapPoint: snapResult ? snapResult.point : null
            };
        }

        return { ghostPunches: [], ghostLine: null, snapPoint: null };

    }, [mousePos, activePart, processedGeometry, selectedTool, manualPunchMode, snapMode, punchOrientation, punchOffset, nibbleSettings, punchCreationStep, teachMode]);
};

import { useState, useCallback, useRef, MouseEvent, WheelEvent } from 'react';

export interface ViewBox {
    x: number;
    y: number;
    width: number;
    height: number;
}

/**
 * **usePanAndZoom**
 * 
 * Provides state and event handlers for an SVG Pan-and-Zoom viewport.
 * 
 * **Features:**
 * - Zoom on Wheel (centered on mouse pointer).
 * - Pan on Mouse Drag (Left Click).
 * - Distinguishes between "Click" (Placement) and "Drag" (Pan) to prevent accidental punches after panning.
 * - Coordinate Transformation: Converts Screen/Event coordinates (Pixels) to SVG ViewBox coordinates (World Units).
 * 
 * **Usage:**
 * Spread the `panZoomHandlers` onto the SVG element and pass `svgRef` to it.
 * 
 * @param {ViewBox} initialViewBox - The starting coordinate system (x, y, width, height).
 * @param {Object} options - Configuration.
 * @param {(point: {x: number, y: number}) => void} options.onClick - Callback fired only if a click was NOT a drag.
 * 
 * @returns {Object} Contains `viewBox` state, `svgRef` for the element, and `panZoomHandlers` for events.
 */
export const usePanAndZoom = (
    initialViewBox: ViewBox,
    options?: { onClick?: (point: { x: number; y: number }) => void }
) => {
    const [viewBox, setViewBox] = useState<ViewBox>(initialViewBox);
    const [isDragging, setIsDragging] = useState(false);

    const svgRef = useRef<SVGSVGElement>(null);
    const isDown = useRef(false);
    const startDragPoint = useRef({ x: 0, y: 0 });
    const lastDragPoint = useRef({ x: 0, y: 0 });


    const getPointFromEvent = useCallback((event: MouseEvent<SVGSVGElement> | WheelEvent<SVGSVGElement>) => {
        if (!svgRef.current) return { x: 0, y: 0 };
        const svg = svgRef.current;
        const CTM = svg.getScreenCTM();
        if (!CTM) return { x: 0, y: 0 };
        return {
            x: (event.clientX - CTM.e) / CTM.a,
            y: (event.clientY - CTM.f) / CTM.d
        };
    }, []);

    const onWheel = useCallback((event: WheelEvent<SVGSVGElement>) => {
        event.preventDefault();
        const point = getPointFromEvent(event);
        const scale = event.deltaY < 0 ? 0.9 : 1.1;

        setViewBox(prev => {
            const newWidth = prev.width * scale;
            const newHeight = prev.height * scale;
            const newX = point.x - (point.x - prev.x) * scale;
            const newY = point.y - (point.y - prev.y) * scale;
            return { x: newX, y: newY, width: newWidth, height: newHeight };
        });
    }, [getPointFromEvent]);

    const onMouseDown = useCallback((event: MouseEvent<SVGSVGElement>) => {
        if (event.button !== 0) return; // Only main button
        isDown.current = true;
        setIsDragging(false);
        startDragPoint.current = { x: event.clientX, y: event.clientY };
        lastDragPoint.current = { x: event.clientX, y: event.clientY };
    }, []);

    const onMouseMove = useCallback((event: MouseEvent<SVGSVGElement>) => {
        if (!isDown.current) return;
        event.preventDefault();

        const dx = event.clientX - startDragPoint.current.x;
        const dy = event.clientY - startDragPoint.current.y;

        if (!isDragging && (Math.abs(dx) > 5 || Math.abs(dy) > 5)) {
            setIsDragging(true);
        }

        if (isDragging) {
            const CTM = svgRef.current?.getScreenCTM();
            if (!CTM) return;

            const panX = (event.clientX - lastDragPoint.current.x) / CTM.a;
            const panY = (event.clientY - lastDragPoint.current.y) / CTM.d;

            setViewBox(prev => ({ ...prev, x: prev.x - panX, y: prev.y - panY }));
            lastDragPoint.current = { x: event.clientX, y: event.clientY };
        }
    }, [isDragging]);

    const onMouseUp = useCallback((event: MouseEvent<SVGSVGElement>) => {
        // A click is registered if the mouse was pressed down in the SVG area
        // and released without significant dragging. This is more reliable than
        // checking the event target, ensuring clicks on part geometry trigger placement.
        if (!isDragging && isDown.current) {
            // Child elements with their own specific interactions (like placed punches) must use
            // e.stopPropagation() in their onClick handlers to prevent this generic handler from firing.
            if (options?.onClick) {
                const point = getPointFromEvent(event);
                options.onClick(point);
            }
        }
        isDown.current = false;
        setIsDragging(false);
    }, [isDragging, options, getPointFromEvent]);

    const onMouseLeave = useCallback(() => {
        isDown.current = false;
        setIsDragging(false);
    }, []);

    return {
        svgRef,
        viewBox,
        setViewBox,
        isDragging,
        getPointFromEvent,
        panZoomHandlers: {
            onWheel,
            onMouseDown,
            onMouseMove,
            onMouseUp,
            onMouseLeave,
        }
    };
};

import React, { useState, useEffect } from 'react';

/**
 * **useLocalStorage**
 * 
 * A React hook that persists state to `localStorage`.
 * It behaves like `useState` but synchronizes with the browser's storage.
 * 
 * **Features:**
 * - Lazy initialization (reads from storage only on mount).
 * - Graceful error handling (fallback to initial value if storage fails).
 * - Type-safe via generics.
 * 
 * **Usage Example:**
 * ```tsx
 * const [username, setUsername] = useLocalStorage<string>('user_name', 'Guest');
 * ```
 * 
 * @template T The type of the state variable.
 * @param {string} key The localStorage key.
 * @param {T} initialValue The default value if the key doesn't exist.
 * @returns {[T, React.Dispatch<React.SetStateAction<T>>]} Tuple of [storedValue, setValue].
 */
export function useLocalStorage<T>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  // Get from local storage then parse stored json or return initialValue
  const readValue = (): T => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  };

  const [storedValue, setStoredValue] = useState<T>(readValue);

  // Return a wrapped version of useState's setter function that ...
  // ... persists the new value to localStorage.
  const setValue: React.Dispatch<React.SetStateAction<T>> = (value) => {
    try {
      // Allow value to be a function so we have same API as useState
      const valueToStore = value instanceof Function ? value(storedValue) : value;

      // Save state
      setStoredValue(valueToStore);

      // Save to local storage
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

