        selectedSegmentIds: props.selectedSegmentIds,
        selectedTeachPunchIds: props.selectedTeachPunchIds,
        onTeachBulkSelect: props.onTeachBulkSelect,
        selectedNestPartId: props.selectedNestPartId,
