                }}
                handlers={{
                    onSaveTeachCycle: props.onSaveTeachCycle,
                    onRunOptimization: props.onRunOptimization
                }}
                activeNest={activeNest}
                activeSheetIndex={props.activeSheetIndex}
            />
        </div>
    );
};

