import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { 
    AppMode, Tool, Part, NestLayout, TurretLayout, MachineSettings, OptimizerSettings, 
    ParametricScript, TeachCycle, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings,
    ToastMessage, PunchOp, ScheduledPart
} from '../types';
import { initialTools, initialParts, initialScripts, initialNests, initialTurretLayouts, defaultMachineSettings, defaultOptimizerSettings } from '../data/initialData';
import { generateId } from '../utils/helpers';
import { ProcessedGeometry, getGeometryFromEntities } from '../services/geometry';

// --- Types ---

interface DataSlice {
    tools: Tool[];
    parts: Part[];
    scripts: ParametricScript[];
    nests: NestLayout[];
    turretLayouts: TurretLayout[];
    machineSettings: MachineSettings;
    optimizerSettings: OptimizerSettings;
    teachCycles: TeachCycle[];

    setTools: (tools: Tool[] | ((prev: Tool[]) => Tool[])) => void;
    setParts: (parts: Part[] | ((prev: Part[]) => Part[])) => void;
    setScripts: (scripts: ParametricScript[] | ((prev: ParametricScript[]) => ParametricScript[])) => void;
    setNests: (nests: NestLayout[] | ((prev: NestLayout[]) => NestLayout[])) => void;
    setTurretLayouts: (layouts: TurretLayout[]) => void;
    setMachineSettings: (settings: MachineSettings) => void;
    setOptimizerSettings: (settings: OptimizerSettings) => void;
    setTeachCycles: (cycles: TeachCycle[] | ((prev: TeachCycle[]) => TeachCycle[])) => void;
}

interface EditorSlice {
    mode: AppMode;
    setMode: (mode: AppMode) => void;

    activePartId: string | null;
    setActivePartId: (id: string | null) => void;

    // Derived/Computed getters helpers
    getActivePart: () => Part | null;
    getActivePartProcessedGeometry: () => ProcessedGeometry | null;

    selectedToolId: string | null;
    setSelectedToolId: (id: string | null) => void;

    selectedPunchId: string | null;
    setSelectedPunchId: (id: string | null) => void;

    manualPunchMode: ManualPunchMode;
    setManualPunchMode: (mode: ManualPunchMode) => void;

    snapMode: SnapMode;
    setSnapMode: (mode: SnapMode) => void;

    punchOrientation: number;
    setPunchOrientation: (angle: number) => void;

    punchOffset: number;
    setPunchOffset: (offset: number) => void;

    nibbleSettings: NibbleSettings;
    setNibbleSettings: (settings: NibbleSettings) => void;

    destructSettings: DestructSettings;
    setDestructSettings: (settings: DestructSettings) => void;

    // Teach Mode
    teachMode: boolean;
    setTeachMode: (enabled: boolean) => void;
    selectedSegmentIds: number[];
    setSelectedSegmentIds: (ids: number[] | ((prev: number[]) => number[])) => void;
    selectedTeachPunchIds: string[];
    setSelectedTeachPunchIds: (ids: string[] | ((prev: string[]) => string[])) => void;
}

interface NestingSlice {
    activeNestId: string | null;
    setActiveNestId: (id: string | null) => void;
    activeSheetIndex: number;
    setActiveSheetIndex: (index: number) => void;
    selectedNestPartId: string | null;
    setSelectedNestPartId: (id: string | null) => void;

    isNestingProcessing: boolean;
    setIsNestingProcessing: (val: boolean) => void;
    nestingProgress: number;
    setNestingProgress: (val: number) => void;
    nestingStatus: string;
    setNestingStatus: (val: string) => void;

    // Helpers
    getActiveNest: () => NestLayout | null;
}

interface SimulationSlice {
    optimizedOperations: PunchOp[] | null;
    setOptimizedOperations: (ops: PunchOp[] | null) => void;
    simulationStep: number;
    setSimulationStep: (step: number | ((prev: number) => number)) => void;
    isSimulating: boolean;
    setIsSimulating: (val: boolean) => void;
    simulationSpeed: number;
    setSimulationSpeed: (speed: number) => void;
}

interface UISlice {
    toasts: ToastMessage[];
    addToast: (message: string, type: ToastMessage['type']) => void;
    removeToast: (id: string) => void;

    // Modals
    showGCodeModal: boolean;
    setShowGCodeModal: (val: boolean) => void;
    showOptimizerModal: boolean;
    setShowOptimizerModal: (val: boolean) => void;
    showAutoPunchSettingsModal: boolean;
    setShowAutoPunchSettingsModal: (val: boolean) => void;
    showTeachSaveModal: boolean;
    setShowTeachSaveModal: (val: boolean) => void;

    isGeneratingGCode: boolean;
    setIsGeneratingGCode: (val: boolean) => void;
    generatedGCode: string;
    setGeneratedGCode: (code: string) => void;
}

// --- Store Creation ---

interface AppState extends DataSlice, EditorSlice, NestingSlice, SimulationSlice, UISlice {}

export const useStore = create<AppState>()(
    persist(
        (set, get) => ({
            // --- Data Slice ---
            tools: initialTools,
            parts: initialParts,
            scripts: initialScripts,
            nests: initialNests,
            turretLayouts: initialTurretLayouts,
            machineSettings: defaultMachineSettings,
            optimizerSettings: defaultOptimizerSettings,
            teachCycles: [],

            setTools: (tools) => set((state) => ({ tools: typeof tools === 'function' ? tools(state.tools) : tools })),
            setParts: (parts) => set((state) => ({ parts: typeof parts === 'function' ? parts(state.parts) : parts })),
            setScripts: (scripts) => set((state) => ({ scripts: typeof scripts === 'function' ? scripts(state.scripts) : scripts })),
            setNests: (nests) => set((state) => ({ nests: typeof nests === 'function' ? nests(state.nests) : nests })),
            setTurretLayouts: (layouts) => set({ turretLayouts: layouts }),
            setMachineSettings: (settings) => set({ machineSettings: settings }),
            setOptimizerSettings: (settings) => set({ optimizerSettings: settings }),
            setTeachCycles: (cycles) => set((state) => ({ teachCycles: typeof cycles === 'function' ? cycles(state.teachCycles) : cycles })),

            // --- Editor Slice ---
            mode: AppMode.PartEditor,
            setMode: (mode) => set({ mode }),

            activePartId: null,
            setActivePartId: (id) => set({ activePartId: id, selectedPunchId: null, teachMode: false }),

            getActivePart: () => {
                const { parts, activePartId } = get();
                return parts.find(p => p.id === activePartId) || null;
            },
            getActivePartProcessedGeometry: () => {
                const part = get().getActivePart();
                return part ? getGeometryFromEntities(part) : null;
            },

            selectedToolId: null,
            setSelectedToolId: (id) => set({ selectedToolId: id }),

            selectedPunchId: null,
            setSelectedPunchId: (id) => set({ selectedPunchId: id }),

            manualPunchMode: ManualPunchMode.Punch,
            setManualPunchMode: (mode) => set({ manualPunchMode: mode }),

            snapMode: SnapMode.Vertex,
            setSnapMode: (mode) => set({ snapMode: mode }),

            punchOrientation: 0,
            setPunchOrientation: (angle) => set({ punchOrientation: angle }),

            punchOffset: 0,
            setPunchOffset: (offset) => set({ punchOffset: offset }),

            nibbleSettings: { extensionStart: 0, extensionEnd: 0, minOverlap: 1, hitPointMode: 'offset', toolPosition: 'long' },
            setNibbleSettings: (settings) => set({ nibbleSettings: settings }),

            destructSettings: { overlap: 0.7, scallop: 0.25, notchExpansion: 0.25 },
            setDestructSettings: (settings) => set({ destructSettings: settings }),

            teachMode: false,
            setTeachMode: (enabled) => set({ teachMode: enabled, selectedSegmentIds: [], selectedTeachPunchIds: [] }),
            selectedSegmentIds: [],
            setSelectedSegmentIds: (ids) => set((state) => ({ selectedSegmentIds: typeof ids === 'function' ? ids(state.selectedSegmentIds) : ids })),
            selectedTeachPunchIds: [],
            setSelectedTeachPunchIds: (ids) => set((state) => ({ selectedTeachPunchIds: typeof ids === 'function' ? ids(state.selectedTeachPunchIds) : ids })),

            // --- Nesting Slice ---
            activeNestId: initialNests[0]?.id || null,
            setActiveNestId: (id) => set({ activeNestId: id }),
            activeSheetIndex: 0,
            setActiveSheetIndex: (index) => set({ activeSheetIndex: index }),
            selectedNestPartId: null,
            setSelectedNestPartId: (id) => set({ selectedNestPartId: id }),
            isNestingProcessing: false,
            setIsNestingProcessing: (val) => set({ isNestingProcessing: val }),
            nestingProgress: 0,
            setNestingProgress: (val) => set({ nestingProgress: val }),
            nestingStatus: '',
            setNestingStatus: (val) => set({ nestingStatus: val }),
            getActiveNest: () => {
                const { nests, activeNestId } = get();
                return nests.find(n => n.id === activeNestId) || null;
            },

            // --- Simulation Slice ---
            optimizedOperations: null,
            setOptimizedOperations: (ops) => set({ optimizedOperations: ops }),
            simulationStep: 0,
            setSimulationStep: (step) => set((state) => ({ simulationStep: typeof step === 'function' ? step(state.simulationStep) : step })),
            isSimulating: false,
            setIsSimulating: (val) => set({ isSimulating: val }),
            simulationSpeed: 50,
            setSimulationSpeed: (val) => set({ simulationSpeed: val }),

            // --- UI Slice ---
            toasts: [],
            addToast: (message, type) => set((state) => ({ toasts: [...state.toasts, { id: generateId(), message, type }] })),
            removeToast: (id) => set((state) => ({ toasts: state.toasts.filter(t => t.id !== id) })),

            showGCodeModal: false,
            setShowGCodeModal: (val) => set({ showGCodeModal: val }),
            showOptimizerModal: false,
            setShowOptimizerModal: (val) => set({ showOptimizerModal: val }),
            showAutoPunchSettingsModal: false,
            setShowAutoPunchSettingsModal: (val) => set({ showAutoPunchSettingsModal: val }),
            showTeachSaveModal: false,
            setShowTeachSaveModal: (val) => set({ showTeachSaveModal: val }),
            isGeneratingGCode: false,
            setIsGeneratingGCode: (val) => set({ isGeneratingGCode: val }),
