        }),
        {
            name: 'fp-studio-storage',
            storage: createJSONStorage(() => localStorage),
            partialize: (state) => ({ 
                // Persist only data, not UI transient state
                tools: state.tools,
                parts: state.parts,
                scripts: state.scripts,
                nests: state.nests,
                turretLayouts: state.turretLayouts,
                machineSettings: state.machineSettings,
                optimizerSettings: state.optimizerSettings,
                teachCycles: state.teachCycles
            }),
        }
    )
);

/**
 * ОТВЕТСТВЕННОСТЬ: Бизнес-логика высокого уровня (complex handlers).
 * Теперь этот хук извлекает функции из Zustand Store и предоставляет сложные обработчики (раскрой, G-код).
 */
import React from 'react';
import { useStore } from '../store/useStore';
import { nestingGenerator } from '../services/nesting';
import { generateGCode, calculateOptimizedPath } from '../services/gcode';
import { generateContourPunches } from '../services/punching';
import { createTeachCycleFromSelection } from '../services/teachLogic';
import { generateId } from '../utils/helpers';
import { AutoPunchSettings, OptimizerSettings } from '../types';
import { useFileImport } from './useFileImport';

export const useAppLogic = () => {
    const store = useStore();

    // --- Async / Complex Logic Handlers ---

    const handleRunNesting = async () => {
        const activeNest = store.getActiveNest();
        if(!activeNest || activeNest.scheduledParts.length === 0) return;

        store.setIsNestingProcessing(true);
        store.setNestingProgress(0);
        store.setNestingStatus('Инициализация...');

        // Clear sheets
        store.setNests(prev => prev.map(x => x.id === activeNest.id ? {...x, sheets: []} : x)); 
        store.setActiveSheetIndex(0);

        try {
            for await (const update of nestingGenerator(activeNest.scheduledParts, store.parts, store.tools, activeNest.settings)) {
                store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, sheets: update.sheets } : n));
                store.setNestingProgress(update.progress);
                store.setNestingStatus(update.status);
            }
            store.addToast("Раскрой завершен", "success");
        } catch(e) {
            const errorMsg = e instanceof Error ? e.message : String(e);
            store.addToast("Ошибка раскроя: " + errorMsg, "error");
        } finally {
            store.setIsNestingProcessing(false);
        }
    };

    const onRunOptimization = (finalSettings: OptimizerSettings) => {
        const activeNest = store.getActiveNest();
        const currentNestSheet = activeNest?.sheets[store.activeSheetIndex];

        if (!currentNestSheet) return;

        store.setOptimizerSettings(finalSettings);
        store.setShowOptimizerModal(false);

        const ops = calculateOptimizedPath(currentNestSheet, store.parts, store.tools, finalSettings);
        store.setOptimizedOperations(ops);
        store.setSimulationStep(0); 

        if (store.isGeneratingGCode) {
            const programNumber = store.activeSheetIndex + 1;
            const ncFilename = activeNest?.workOrder ? `${activeNest.workOrder}_${programNumber}.nc` : `Program_${programNumber}.nc`;
            const code = generateGCode(currentNestSheet, store.parts, store.tools, ncFilename, store.machineSettings, finalSettings, activeNest?.settings.clampPositions, programNumber, ops);
            store.setGeneratedGCode(code);
            store.setShowGCodeModal(true);
        } else {
            store.addToast(`Оптимизация завершена. ${ops.length} операций.`, "success");
        }
    };

    const downloadGCode = () => {
        const activeNest = store.getActiveNest();
        const blob = new Blob([store.generatedGCode], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = activeNest?.workOrder ? `${activeNest.workOrder}_${store.activeSheetIndex + 1}.nc` : `Program_${store.activeSheetIndex + 1}.nc`;
        document.body.appendChild(link); link.click(); document.body.removeChild(link); URL.revokeObjectURL(url);
    };

    const onAutoPunchApply = (s: AutoPunchSettings) => { 
        const activePart = store.getActivePart();
        if (!activePart) return;

        const p = generateContourPunches(activePart.geometry, store.tools, s, store.turretLayouts, store.teachCycles); 

        // Update part in store
        const newPunches = p.map(px => ({...px, id: generateId()}));
        const updatedPart = { ...activePart, punches: [...activePart.punches, ...newPunches] };

        store.setParts(parts => parts.map(pt => pt.id === updatedPart.id ? updatedPart : pt));

        store.setShowAutoPunchSettingsModal(false); 
        store.addToast(`Сгенерировано: ${p.length}`, "success"); 
    };

    const onSaveTeachCycle = (name: string, symmetry: any) => {
        const activePart = store.getActivePart();
        const geometry = store.getActivePartProcessedGeometry();
        if (!activePart || !geometry) return;

        const cycle = createTeachCycleFromSelection(name, symmetry, store.selectedSegmentIds, store.selectedTeachPunchIds, activePart, geometry);
        if (cycle) { 
            store.setTeachCycles(prev => [...prev, cycle]); 
            store.setTeachMode(false); 
        }
        store.setShowTeachSaveModal(false);
    };

    // Wrapper for File Import to update Store
    const { handleFileUpload } = useFileImport({ 
        tools: store.tools, 
        setMode: store.setMode, 
        setActivePart: (part) => {
            store.setParts(prev => [...prev.filter(p => p.id !== part.id), part]);
            store.setActivePartId(part.id);
        }, 
        addToast: store.addToast 
    });

    return {
        handleRunNesting,
        onRunOptimization,
        downloadGCode,
        onAutoPunchApply,
        onSaveTeachCycle,
        handleFileUpload
    };
};

