export const AppUI: React.FC = () => {
    // 1. Store State & Setters
    const store = useStore();
    const { 
        mode, setMode, 
        tools, parts, scripts, nests, turretLayouts, machineSettings, optimizerSettings, teachCycles,
        activeSheetIndex, setActiveSheetIndex,
        selectedNestPartId, setSelectedNestPartId,
        isNestingProcessing, nestingProgress, nestingStatus,
        optimizedOperations, simulationStep, isSimulating, simulationSpeed,
        toasts, removeToast,
        setParts, setTools, setScripts, setTurretLayouts, setMachineSettings,
        setOptimizedOperations, setSimulationStep, setIsSimulating, setSimulationSpeed,
        setShowTeachSaveModal, setShowAutoPunchSettingsModal, setShowOptimizerModal, setShowGCodeModal,
        generatedGCode, isGeneratingGCode
    } = store;

    const activeNest = store.getActiveNest();

    // 2. Logic Handlers
    const logic = useAppLogic();
    const { confirm, confirmationState, closeConfirmation } = useConfirmation();
    const panZoom = usePanAndZoom({ x: 0, y: 0, width: 2500, height: 1250 }); // Default viewBox

    // 3. Editor Logic (with local handlers)
    const handleAddPunches = (newPunches: Omit<PlacedTool, 'id'>[]) => {
        const activePartId = store.activePartId;
        if (!activePartId) return;

        setParts(prev => prev.map(p => {
            if (p.id === activePartId) {
                const punchesToAdd = newPunches.map(np => ({ ...np, id: generateId() }));
                return { ...p, punches: [...p.punches, ...punchesToAdd] };
            }
            return p;
        }));
    };

    const editorState = useEditorState({ 
        tools, 
        onAddPunches: handleAddPunches 
    });

    // 4. Props Construction for Dumb Components
    const sidebarProps = {
        mode,
        parts,
        activePart: editorState.activePart,
        activePartId: store.activePartId,
        setActivePartId: store.setActivePartId,
        onDeletePart: (id: string) => setParts(prev => prev.filter(p => p.id !== id)),
        tools,
        activeNest,
        activeSheetIndex,
        setActiveSheetIndex,
        onFileUpload: logic.handleFileUpload,

        // Manual Punch Props
        manualPunchMode: editorState.manualPunchMode,
        setManualPunchMode: editorState.setManualPunchMode,
        selectedToolId: editorState.selectedToolId,
        setSelectedToolId: editorState.setSelectedToolId,
        selectedPunchId: editorState.selectedPunchId,
        setSelectedPunchId: editorState.setSelectedPunchId,
        onDeletePunch: (id: string | string[]) => {
            const ids = Array.isArray(id) ? id : [id];
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.filter(x => !ids.includes(x.id)) } 
                    : p
            ));
            editorState.setSelectedPunchId(null);
        },
        onUpdatePunch: (id: string, updates: Partial<PlacedTool>) => {
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.map(x => x.id === id ? { ...x, ...updates } : x) } 
                    : p
            ));
        },
        onClearAllPunches: () => {
            confirm('Очистить все', 'Вы уверены, что хотите удалить все удары?', () => {
                setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, punches: [] } : p));
            });
        },
        punchOrientation: editorState.punchOrientation,
        setPunchOrientation: editorState.setPunchOrientation,
        onCyclePunchOrientation: () => editorState.setPunchOrientation((editorState.punchOrientation + 90) % 360),
        snapMode: editorState.snapMode,
        setSnapMode: editorState.setSnapMode,
        punchOffset: editorState.punchOffset,
        setPunchOffset: editorState.setPunchOffset,

        nibbleSettings: editorState.nibbleSettings,
        setNibbleSettings: editorState.setNibbleSettings,
        destructSettings: editorState.destructSettings,
        setDestructSettings: editorState.setDestructSettings,

        // Nesting Settings
        onUpdateNestingSettings: (s: any, sp: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, settings: s, scheduledParts: sp } : n)),
        onUpdateNestMetadata: (m: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, ...m } : n)),

        // Actions
        onOpenTurretView: () => setMode(AppMode.TurretSetup),
        onSavePartAsScript: () => { /* Implement if needed or use header/secondary logic */ },
        onSavePartAsStatic: () => {
             const ap = editorState.activePart;
             if (ap && activeNest) {
                 const newPart = { ...ap, id: generateId(), name: `${ap.name}_copy` };
                 setParts(prev => [...prev, newPart]);
                 store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, scheduledParts: [...n.scheduledParts, { partId: newPart.id, quantity: 1, nesting: ap.nesting }] } : n));
                 store.addToast('Деталь сохранена в раскрой', 'success');
             }
        },
        onUpdateActivePart: (u: Partial<Part>) => setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, ...u } : p)),
        onClosePart: () => store.setActivePartId(null),

        // Teach Mode
        teachMode: editorState.teachMode,
        setTeachMode: editorState.setTeachMode,
        onSaveTeachCycle: () => setShowTeachSaveModal(true),
        teachCycles,
        onDeleteTeachCycle: (id: string) => store.setTeachCycles(prev => prev.filter(c => c.id !== id)),

        // Nesting Actions
        onRunNesting: logic.handleRunNesting,
        isNestingProcessing,
        nestingProgress,
        nestingStatus,
        onClearNest: () => confirm('Сброс раскроя', 'Удалить все результаты?', () => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, sheets: [] } : n))),
        selectedNestPartId,
        onMoveNestPart: (id: string, dx: number, dy: number) => {
            store.setNests(prev => prev.map(n => {
