        allParts: parts,
        simulationStep,
        totalSimulationSteps: optimizedOperations ? optimizedOperations.length : 0,
        isSimulating,
        simulationSpeed,
        onToggleSimulation: () => setIsSimulating(!isSimulating),
        onStopSimulation: () => { setIsSimulating(false); setSimulationStep(0); },
        onStepChange: setSimulationStep,
        onSpeedChange: setSimulationSpeed,
        optimizedOperations,
    };

