    return (
        <div className="flex flex-col h-full font-sans relative overflow-hidden">
            <HeaderBar 
                onGenerateGCode={() => { store.setIsGeneratingGCode(true); setShowOptimizerModal(true); }} 
                onOptimizePath={() => { store.setIsGeneratingGCode(false); setShowOptimizerModal(true); }}
            />

            <div className="flex flex-1 overflow-hidden bg-gray-900">
                {isMainMode ? (
                    <MainWorkspace 
                        mode={mode}
                        sidebarProps={sidebarProps}
