                return { ...p, punches: [...p.punches, ...punchesToAdd] };
            }
            return p;
        }));
    };

    const editorState = useEditorState({ 
        tools, 
        onAddPunches: handleAddPunches 
    });

    // 4. Props Construction for Dumb Components
    const sidebarProps = {
        mode,
        parts,
        activePart: editorState.activePart,
        activePartId: store.activePartId,
        setActivePartId: store.setActivePartId,
        onDeletePart: (id: string) => setParts(prev => prev.filter(p => p.id !== id)),
        tools,
        activeNest,
        activeSheetIndex,
        setActiveSheetIndex,
        onFileUpload: logic.handleFileUpload,

        // Manual Punch Props
        manualPunchMode: editorState.manualPunchMode,
        setManualPunchMode: editorState.setManualPunchMode,
        selectedToolId: editorState.selectedToolId,
        setSelectedToolId: editorState.setSelectedToolId,
        selectedPunchId: editorState.selectedPunchId,
        setSelectedPunchId: editorState.setSelectedPunchId,
        onDeletePunch: (id: string | string[]) => {
            const ids = Array.isArray(id) ? id : [id];
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.filter(x => !ids.includes(x.id)) } 
                    : p
            ));
            editorState.setSelectedPunchId(null);
        },
        onUpdatePunch: (id: string, updates: Partial<PlacedTool>) => {
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.map(x => x.id === id ? { ...x, ...updates } : x) } 
                    : p
            ));
        },
        onClearAllPunches: () => {
            confirm('Очистить все', 'Вы уверены, что хотите удалить все удары?', () => {
                setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, punches: [] } : p));
            });
        },
        punchOrientation: editorState.punchOrientation,
        setPunchOrientation: editorState.setPunchOrientation,
        onCyclePunchOrientation: () => editorState.setPunchOrientation((editorState.punchOrientation + 90) % 360),
        snapMode: editorState.snapMode,
        setSnapMode: editorState.setSnapMode,
        punchOffset: editorState.punchOffset,
        setPunchOffset: editorState.setPunchOffset,

        nibbleSettings: editorState.nibbleSettings,
        setNibbleSettings: editorState.setNibbleSettings,
        destructSettings: editorState.destructSettings,
        setDestructSettings: editorState.setDestructSettings,

        // Nesting Settings
        onUpdateNestingSettings: (s: any, sp: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, settings: s, scheduledParts: sp } : n)),
        onUpdateNestMetadata: (m: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, ...m } : n)),

        // Actions
        onOpenTurretView: () => setMode(AppMode.TurretSetup),
        onSavePartAsScript: () => { /* Implement if needed or use header/secondary logic */ },
        onSavePartAsStatic: () => {
             const ap = editorState.activePart;
             if (ap && activeNest) {
                 const newPart = { ...ap, id: generateId(), name: `${ap.name}_copy` };
                 setParts(prev => [...prev, newPart]);
                 store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, scheduledParts: [...n.scheduledParts, { partId: newPart.id, quantity: 1, nesting: ap.nesting }] } : n));
                 store.addToast('Деталь сохранена в раскрой', 'success');
             }
        },
        onUpdateActivePart: (u: Partial<Part>) => setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, ...u } : p)),
        onClosePart: () => store.setActivePartId(null),

        // Teach Mode
        teachMode: editorState.teachMode,
        setTeachMode: editorState.setTeachMode,
        onSaveTeachCycle: () => setShowTeachSaveModal(true),
        teachCycles,
        onDeleteTeachCycle: (id: string) => store.setTeachCycles(prev => prev.filter(c => c.id !== id)),

        // Nesting Actions
        onRunNesting: logic.handleRunNesting,
        isNestingProcessing,
        nestingProgress,
        nestingStatus,
        onClearNest: () => confirm('Сброс раскроя', 'Удалить все результаты?', () => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, sheets: [] } : n))),
        selectedNestPartId,
        onMoveNestPart: (id: string, dx: number, dy: number) => {
            store.setNests(prev => prev.map(n => {
                if (n.id !== store.activeNestId) return n;
                const sheets = n.sheets.map((s, idx) => {
                    if (idx !== activeSheetIndex) return s;
                    return { ...s, placedParts: s.placedParts.map(pp => pp.id === id ? { ...pp, x: pp.x + dx, y: pp.y + dy } : pp) };
                });
                return { ...n, sheets };
            }));
        },
        onRotateNestPart: (id: string) => {
            store.setNests(prev => prev.map(n => {
                if (n.id !== store.activeNestId) return n;
                const sheets = n.sheets.map((s, idx) => {
                    if (idx !== activeSheetIndex) return s;
                    return { ...s, placedParts: s.placedParts.map(pp => pp.id === id ? { ...pp, rotation: (pp.rotation + 90) % 360 } : pp) };
                });
                return { ...n, sheets };
            }));
        },
    };

    const canvasProps = {
        mode,
        activePart: editorState.activePart,
        processedGeometry: editorState.activePartProcessedGeometry,
        activeNest,
        currentNestSheet: activeNest?.sheets[activeSheetIndex] || null,
        tools,
        parts,
        svgRef: panZoom.svgRef,
        viewBox: panZoom.viewBox,
        setViewBox: panZoom.setViewBox,
        isDragging: panZoom.isDragging,
        getPointFromEvent: panZoom.getPointFromEvent,
        panZoomHandlers: panZoom.panZoomHandlers,
        onOpenAutoPunchSettings: () => setShowAutoPunchSettingsModal(true),
        punchCreationStep: editorState.manualPunch.punchCreationStep,
        punchCreationPoints: editorState.manualPunch.punchCreationPoints,
        manualPunchMode: editorState.manualPunchMode,
        selectedToolId: editorState.selectedToolId,
        selectedPunchId: editorState.selectedPunchId,
        onSelectPunch: editorState.setSelectedPunchId,
        placementReference: 0 as any,
        placementSide: 0 as any,
        punchOrientation: editorState.punchOrientation,
        snapMode: editorState.snapMode,
        punchOffset: editorState.punchOffset,
        nibbleSettings: editorState.nibbleSettings,
        teachMode: editorState.teachMode,
        selectedSegmentIds: editorState.selectedSegmentIds,
        selectedTeachPunchIds: editorState.selectedTeachPunchIds,
        onTeachBulkSelect: (segs: number[], punches: string[], add: boolean) => {
            if (add) {
                editorState.setSelectedSegmentIds(prev => [...new Set([...prev, ...segs])]);
                editorState.setSelectedTeachPunchIds(prev => [...new Set([...prev, ...punches])]);
            } else {
                editorState.setSelectedSegmentIds(segs);
                editorState.setSelectedTeachPunchIds(punches);
            }
        },
        selectedNestPartId,
        onSelectNestPart: setSelectedNestPartId,
        onMoveNestPart: sidebarProps.onMoveNestPart,
        optimizedOperations,
        simulationStep,
        onCanvasClick: editorState.manualPunch.handleCanvasClick // Implicitly used by PartEditorCanvas logic or separate handler
    };

    const rightPanelProps = {
        tools,
        selectedToolId: editorState.selectedToolId,
        setSelectedToolId: editorState.setSelectedToolId,
        onOpenTurretView: () => setMode(AppMode.TurretSetup),
        activeNest,
        allParts: parts,
        simulationStep,
        totalSimulationSteps: optimizedOperations ? optimizedOperations.length : 0,
        isSimulating,
        simulationSpeed,
        onToggleSimulation: () => setIsSimulating(!isSimulating),
        onStopSimulation: () => { setIsSimulating(false); setSimulationStep(0); },
        onStepChange: setSimulationStep,
        onSpeedChange: setSimulationSpeed,
        optimizedOperations,
    };

    const isMainMode = mode === AppMode.PartEditor || mode === AppMode.Nesting;

    return (
        <div className="flex flex-col h-full font-sans relative overflow-hidden">
            <HeaderBar 
                onGenerateGCode={() => { store.setIsGeneratingGCode(true); setShowOptimizerModal(true); }} 
                onOptimizePath={() => { store.setIsGeneratingGCode(false); setShowOptimizerModal(true); }}
            />

            <div className="flex flex-1 overflow-hidden bg-gray-900">
                {isMainMode ? (
                    <MainWorkspace 
                        mode={mode}
                        sidebarProps={sidebarProps}
                        canvasProps={canvasProps}
                        rightPanelProps={rightPanelProps}
                        activeSheetIndex={activeSheetIndex}
                        setActiveSheetIndex={setActiveSheetIndex}
                    />
                ) : (
                    <SecondaryViewManager 
                        mode={mode}
                        data={{
                            partLibrary: { parts, tools },
                            scriptLibrary: { scripts, tools, parts },
                            toolLibrary: { tools },
                            turretSetup: { tools, layouts: turretLayouts },
                            machineSetup: { settings: machineSettings }
                        }}
                        handlers={{
                            partLibrary: { 
                                onLoadPart: (p: Part) => { setParts(prev => [...prev.filter(x => x.id !== p.id), p]); store.setActivePartId(p.id); setMode(AppMode.PartEditor); }, 
                                onDeletePart: sidebarProps.onDeletePart, 
                                onUpdatePart: (p: Part) => setParts(prev => prev.map(x => x.id === p.id ? p : x)) 
                            },
                            scriptLibrary: { 
                                onSaveScript: (s: any) => setScripts(prev => [...prev.filter(x => x.id !== s.id), s]), 
                                onDeleteScript: (id: string) => setScripts(prev => prev.filter(x => x.id !== id)), 
                                onCreatePart: (p: Part) => { setParts(prev => [...prev, p]); store.setActivePartId(p.id); setMode(AppMode.PartEditor); }, 
                                onBatchProcess: (pNew: any[], spNew: any[]) => {
                                    setParts(prev => [...prev, ...pNew]);
                                    if (activeNest) store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, scheduledParts: [...n.scheduledParts, ...spNew] } : n));
                                    store.addToast(`Добавлено ${pNew.length} деталей`, 'success');
                                }
                            },
                            toolLibrary: { 
                                onSaveTool: (t: Tool) => setTools(prev => [...prev.filter(x => x.id !== t.id), t]), 
                                onDeleteTool: (id: string) => setTools(prev => prev.filter(x => x.id !== id)) 
                            },
                            turretSetup: { setTools, setLayouts: setTurretLayouts },
                            machineSetup: { onUpdate: setMachineSettings }
                        }}
                    />
                )}
            </div>

            <ModalRegistry 
                ui={{
                    showAutoPunchSettingsModal: store.showAutoPunchSettingsModal, setShowAutoPunchSettingsModal,
                    showTeachSaveModal: store.showTeachSaveModal, setShowTeachSaveModal,
                    showOptimizerModal: store.showOptimizerModal, setShowOptimizerModal,
                    showGCodeModal: store.showGCodeModal, setShowGCodeModal,
                    toasts, removeToast,
                    generatedGCode,
                    onAutoPunchApply: logic.onAutoPunchApply,
                    downloadGCode: logic.downloadGCode
                }}
                confirmation={{ state: confirmationState, close: closeConfirmation }}
                data={{
                    turretLayouts,
                    optimizerSettings,
                    parts,
                    tools
                }}
                handlers={{
                    onSaveTeachCycle: logic.onSaveTeachCycle,
                    onRunOptimization: logic.onRunOptimization
                }}
                activeNest={activeNest}
                activeSheetIndex={activeSheetIndex}
            />
        </div>
    );
};

/**
 * ОТВЕТСТВЕННОСТЬ: Управление логикой револьвера.
 * Содержит: выбор станций, установку/снятие инструмента, проверку совместимости станций и управление конфигурациями (layouts).
 */
import { useState, useEffect, useCallback, useMemo, Dispatch, SetStateAction } from 'react';
import { Tool, TurretLayout, StationConfig } from '../../types';
import { generateId } from '../../utils/helpers';

interface UseTurretLogicProps {
    tools: Tool[];
    setTools: Dispatch<SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: Dispatch<SetStateAction<TurretLayout[]>>;
}

export const useTurretLogic = ({ tools, setTools, layouts, setLayouts }: UseTurretLogicProps) => {
    const [activeLayoutId, setActiveLayoutId] = useState<string>(layouts[0]?.id || '');
    const [currentStations, setCurrentStations] = useState<StationConfig[]>(layouts[0]?.stations || []);
    const [selectedStationId, setSelectedStationId] = useState<number | null>(null);
    const [isMtView, setIsMtView] = useState(false);
    const [selectedMtSlotId, setSelectedMtSlotId] = useState<number | null>(null);
    const [newLayoutName, setNewLayoutName] = useState('');

    useEffect(() => {
        const layout = layouts.find(l => l.id === activeLayoutId);
        if (layout) {
            setCurrentStations(layout.stations);
        }
    }, [activeLayoutId, layouts]);

    const toolsOnTurret = useMemo(() => tools.filter(t => t.stationNumber !== 0 && t.stationNumber !== undefined), [tools]);
    const availableTools = useMemo(() => tools.filter(t => !t.stationNumber), [tools]);

    const loadLayout = useCallback((layoutId: string) => {
        const layout = layouts.find(l => l.id === layoutId);
        if (!layout) return;
        setTools(JSON.parse(JSON.stringify(layout.toolsSnapshot)));
        setCurrentStations(JSON.parse(JSON.stringify(layout.stations)));
        setActiveLayoutId(layoutId);
        setSelectedStationId(null);
        setIsMtView(false);
        setSelectedMtSlotId(null);
    }, [layouts, setTools]);

    const saveLayout = useCallback(() => {
        if (!newLayoutName.trim()) return;
        const newLayout: TurretLayout = {
            id: generateId(),
            name: newLayoutName,
            toolsSnapshot: JSON.parse(JSON.stringify(tools)),
            stations: JSON.parse(JSON.stringify(currentStations))
        };
        setLayouts(prev => [...prev, newLayout]);
        setActiveLayoutId(newLayout.id);
        setNewLayoutName('');
    }, [newLayoutName, tools, currentStations, setLayouts]);

    const deleteLayout = useCallback((id: string) => {
        if (layouts.length <= 1) return;
        setLayouts(prev => prev.filter(l => l.id !== id));
        if (activeLayoutId === id) {
            loadLayout(layouts[0].id);
        }
    }, [layouts, activeLayoutId, loadLayout, setLayouts]);

    const updateStationConfig = useCallback((id: number, updates: Partial<StationConfig>) => {
        setCurrentStations(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { 
            ...l, 
            stations: currentStations.map(s => s.id === id ? { ...s, ...updates } : s) 
        } : l));
    }, [activeLayoutId, currentStations, setLayouts]);

    const handleStationClick = useCallback((stationId: number) => {
        const station = currentStations.find(s => s.id === stationId);
        if (station?.type === 'MT') {
            setIsMtView(true);
            setSelectedMtSlotId(1);
        }
        setSelectedStationId(stationId);
    }, [currentStations]);

    const checkCompatibility = useCallback((tool: Tool, station: StationConfig): boolean => {
        if (station.type === 'MT') return tool.stationType === 'MT';
        return tool.toolSize === station.type;
    }, []);

    const handleMountTool = useCallback((tool: Tool, mtIndex?: number) => {
        if (!selectedStationId) return;
        const station = currentStations.find(s => s.id === selectedStationId);
        if (!station || !checkCompatibility(tool, station)) return;

        const updatedTools = tools.map(t => {
            if (t.stationNumber === selectedStationId) {
                if (isMtView) {
                    if (t.mtIndex === mtIndex) return { ...t, stationNumber: 0, mtIndex: 0 };
                } else {
                    return { ...t, stationNumber: 0, mtIndex: 0 };
                }
            }
            if (t.id === tool.id) {
                return { ...t, stationNumber: selectedStationId, mtIndex: mtIndex || 0 };
            }
            return t;
        });
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [selectedStationId, currentStations, checkCompatibility, tools, isMtView, activeLayoutId, setTools, setLayouts]);

    const handleUnmountTool = useCallback((toolId: string) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, stationNumber: 0, mtIndex: 0 } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [tools, activeLayoutId, setTools, setLayouts]);

    const updateToolRotation = useCallback((toolId: string, rotation: number) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, defaultRotation: rotation } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [tools, activeLayoutId, setTools, setLayouts]);

    return {
        activeLayoutId, currentStations, selectedStationId, isMtView, setIsMtView,
        selectedMtSlotId, setSelectedMtSlotId, newLayoutName, setNewLayoutName,
        toolsOnTurret, availableTools,
        loadLayout, saveLayout, deleteLayout, updateStationConfig,
        handleStationClick, handleMountTool, handleUnmountTool, updateToolRotation
    };
};

/**
 * ГЛАВНЫЙ ХУК РЕДАКТОРА (Агрегатор)
 * Объединяет специализированные хуки состояния и подключает логику ручной пробивки.
 * Сохраняет интерфейс для useAppLogic.
 */
import { Dispatch, SetStateAction } from 'react';
import { Tool, PlacedTool, Part, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings } from '../types';
import { useActivePartState } from './editor/useActivePartState';
import { usePunchToolState } from './editor/usePunchToolState';
import { usePunchSettingsState } from './editor/usePunchSettingsState';
import { useTeachState } from './editor/useTeachState';
import { useManualPunch } from './useManualPunch';
import { ProcessedGeometry } from '../services/geometry';

interface UseEditorStateProps {
    tools: Tool[];
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
}

export interface UseEditorStateResult {
    activePart: Part | null;
    setActivePart: (part: Part | null | ((prev: Part | null) => Part | null)) => void;
    activePartProcessedGeometry: ProcessedGeometry | null;
    selectedToolId: string | null;
    setSelectedToolId: (id: string | null) => void;
    selectedPunchId: string | null;
    setSelectedPunchId: (id: string | null) => void;
    punchOrientation: number;
    setPunchOrientation: (angle: number) => void;
    snapMode: SnapMode;
    setSnapMode: (mode: SnapMode) => void;
    punchOffset: number;
    setPunchOffset: (offset: number) => void;
    selectedTool: Tool | null;
    manualPunchMode: ManualPunchMode;
    setManualPunchMode: (mode: ManualPunchMode) => void;
    nibbleSettings: NibbleSettings;
    setNibbleSettings: (settings: NibbleSettings) => void;
    destructSettings: DestructSettings;
    setDestructSettings: (settings: DestructSettings) => void;
    teachMode: boolean;
    setTeachMode: (val: boolean) => void;
    selectedSegmentIds: number[];
    setSelectedSegmentIds: Dispatch<SetStateAction<number[]>>;
    selectedTeachPunchIds: string[];
    setSelectedTeachPunchIds: Dispatch<SetStateAction<string[]>>;
    manualPunch: ReturnType<typeof useManualPunch>;
}

/**
 * **useEditorState**
 * 
 * Aggregates all state related to the single Part Editor view.
 * Splits responsibilities into sub-hooks (`useActivePartState`, `usePunchToolState`, etc.)
 * but exposes a unified API for the `App` component.
 * 
 * **Purpose:**
 * - Manages the `ActivePart` currently being edited.
 * - Tracks the selected Tool and Punch configuration (orientation, snap).
 * - Manages the specific `ManualPunchMode` (Single, Nibble, Destruct).
 * - Integrates the `useManualPunch` logic handler.
 * 
 * @param {UseEditorStateProps} props
 * @returns {UseEditorStateResult}
 */
export const useEditorState = ({ tools, onAddPunches }: UseEditorStateProps): UseEditorStateResult => {
    // 1. Распределенное состояние
    const part = useActivePartState();
    const tool = usePunchToolState(tools);
    const settings = usePunchSettingsState();
    const teach = useTeachState();

    // 2. Подключение логики кликов (Manual Punch)
    const manualPunch = useManualPunch({
        activePart: part.activePart,
        activePartProcessedGeometry: part.activePartProcessedGeometry,
        selectedTool: tool.selectedTool,
        manualPunchMode: settings.manualPunchMode,
        punchOrientation: tool.punchOrientation,
        punchOffset: tool.punchOffset,
        snapMode: tool.snapMode,
        nibbleSettings: settings.nibbleSettings,
        destructSettings: settings.destructSettings,
        onAddPunches,
        setSelectedPunchId: tool.setSelectedPunchId
    });

    // 3. Сборка единого объекта (Backward Compatibility)
    return {
        // Состояние детали
        activePart: part.activePart,
        setActivePart: part.setActivePart,
        activePartProcessedGeometry: part.activePartProcessedGeometry,

        // Состояние выбора инструмента
        selectedToolId: tool.selectedToolId,
        setSelectedToolId: tool.setSelectedToolId,
        selectedPunchId: tool.selectedPunchId,
        setSelectedPunchId: tool.setSelectedPunchId,
        punchOrientation: tool.punchOrientation,
        setPunchOrientation: tool.setPunchOrientation,
        snapMode: tool.snapMode,
        setSnapMode: tool.setSnapMode,
        punchOffset: tool.punchOffset,
        setPunchOffset: tool.setPunchOffset,
        selectedTool: tool.selectedTool,

        // Настройки режимов
        manualPunchMode: settings.manualPunchMode,
        setManualPunchMode: settings.setManualPunchMode,
        nibbleSettings: settings.nibbleSettings,
        setNibbleSettings: settings.setNibbleSettings,
        destructSettings: settings.destructSettings,
        setDestructSettings: settings.setDestructSettings,

        // Режим обучения
        teachMode: teach.teachMode,
        setTeachMode: teach.setTeachMode,
        selectedSegmentIds: teach.selectedSegmentIds,
        setSelectedSegmentIds: teach.setSelectedSegmentIds,
        selectedTeachPunchIds: teach.selectedTeachPunchIds,
        setSelectedTeachPunchIds: teach.setSelectedTeachPunchIds,

        // Интеграция логики
        manualPunch
    };
};

import { ChangeEvent } from 'react';
import { AppMode, ManualPunchMode, SnapMode } from './enums.types';
