    overlap: number;
    scallop: number;
    notchExpansion: number;
}

export interface AppUIProps {
    mode: AppMode;
    setMode: (mode: AppMode) => void;
    tools: Tool[];
    parts: Part[];
    scripts: ParametricScript[];
    nests: NestLayout[];
    turretLayouts: TurretLayout[];
