    teachCycles: TeachCycle[];
    activePart: Part | null;
    activePartProcessedGeometry: any;
    manualPunchMode: ManualPunchMode;
    selectedToolId: string | null;
    selectedPunchId: string | null;
    punchOrientation: number;
    snapMode: SnapMode;
    punchOffset: number;
    nibbleSettings: NibbleSettings;
    destructSettings: DestructSettings;
    teachMode: boolean;
    selectedSegmentIds: number[];
    selectedTeachPunchIds: string[];
    activeNest: NestLayout | null;
    activeSheetIndex: number;
    selectedNestPartId: string | null;
    isNestingProcessing: boolean;
    nestingProgress: number;
    nestingStatus: string;
    optimizedOperations: PunchOp[] | null;
    simulationStep: number;
    isSimulating: boolean;
    simulationSpeed: number;
    onGenerateGCodeRequest: () => void;
    onOptimizePathRequest: () => void;
    onRunOptimization: (settings: OptimizerSettings) => void;
    onToggleSimulation: () => void;
    onStopSimulation: () => void;
    onStepSimulation: (step: number) => void;
    onSpeedChange: (speed: number) => void;
    onFileUpload: (event: ChangeEvent<HTMLInputElement>) => void;
    onClearAllPunches: () => void;
    onCanvasClick: (point: { x: number; y: number }) => void;
    onTeachBulkSelect: (segs: number[], punches: string[], add: boolean) => void;
    onTeachModeToggle: (val: boolean) => void;
    onSaveTeachCycle: (name: string, symmetry: any) => void;
    onDeleteTeachCycle: (id: string) => void;
    onDeletePunch: (id: string | string[]) => void;
    onUpdatePunch: (id: string, u: Partial<PlacedTool>) => void;
    onSavePartAsScript: () => void;
    onSavePartAsStatic: () => void;
    onRunNesting: () => void;
    onClearNest: () => void;
    onMoveNestPart: (id: string, dx: number, dy: number) => void;
    onRotateNestPart: (id: string) => void;
    onUpdateNestingSettings: (s: any, sp: ScheduledPart[]) => void;
    onUpdateNestMetadata: (m: any) => void;
    onUpdateActivePart: (u: Partial<Part>) => void;
    onClosePart: () => void;
    onSelectNestPart: (id: string | null) => void;
    onLoadPartFromLibrary: (p: Part) => void;
    onDeletePartFromLibrary: (id: string) => void;
    onUpdatePartInLibrary: (p: Part) => void;
    onSaveScript: (s: ParametricScript) => void;
    onDeleteScript: (id: string) => void;
    onCreatePartFromScript: (p: Part) => void;
    onBatchProcess: (pNew: Part[], spNew: ScheduledPart[]) => void;
    onSaveTool: (t: Tool) => void;
    onDeleteTool: (id: string) => void;
    onUpdateMachineSettings: (s: MachineSettings) => void;
    onUpdateTurretTools: (t: Tool[]) => void;
    onUpdateTurretLayouts: (l: TurretLayout[]) => void;
    ui: any;
    confirmation: any;
    panZoom: any;
    manualPunchState: { step: number; points: any[] };
    setActiveSheetIndex: (idx: number) => void;
    setManualPunchMode: (m: ManualPunchMode) => void;
    setSelectedToolId: (id: string | null) => void;
    setSelectedPunchId: (id: string | null) => void;
    setPunchOrientation: (a: number) => void;
    setSnapMode: (m: SnapMode) => void;
    setPunchOffset: (o: number) => void;
    setNibbleSettings: (s: NibbleSettings) => void;
    setDestructSettings: (s: DestructSettings) => void;
}

/**
 * ОТВЕТСТВЕННОСТЬ: Бизнес-логика высокого уровня (complex handlers).
 * Теперь этот хук извлекает функции из Zustand Store и предоставляет сложные обработчики (раскрой, G-код).
 */
import { useStore } from '../store/useStore';
import { nestingGenerator } from '../services/nesting';
import { generateGCode, calculateOptimizedPath } from '../services/gcode';
import { generateContourPunches } from '../services/punching';
import { createTeachCycleFromSelection } from '../services/teachLogic';
import { generateId } from '../utils/helpers';
import { AutoPunchSettings, OptimizerSettings } from '../types';
import { useFileImport } from './useFileImport';

export const useAppLogic = () => {
    const store = useStore();

    // --- Async / Complex Logic Handlers ---

    const handleRunNesting = async () => {
        const activeNest = store.getActiveNest();
        if(!activeNest || activeNest.scheduledParts.length === 0) return;

        store.setIsNestingProcessing(true);
        store.setNestingProgress(0);
        store.setNestingStatus('Инициализация...');

        // Clear sheets
        store.setNests(prev => prev.map(x => x.id === activeNest.id ? {...x, sheets: []} : x)); 
        store.setActiveSheetIndex(0);

        try {
            for await (const update of nestingGenerator(activeNest.scheduledParts, store.parts, store.tools, activeNest.settings)) {
                store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, sheets: update.sheets } : n));
                store.setNestingProgress(update.progress);
                store.setNestingStatus(update.status);
            }
            store.addToast("Раскрой завершен", "success");
        } catch(e) {
            const errorMsg = e instanceof Error ? e.message : String(e);
            store.addToast("Ошибка раскроя: " + errorMsg, "error");
        } finally {
            store.setIsNestingProcessing(false);
        }
    };

    const onRunOptimization = (finalSettings: OptimizerSettings) => {
        const activeNest = store.getActiveNest();
        const currentNestSheet = activeNest?.sheets[store.activeSheetIndex];

        if (!currentNestSheet) return;

        store.setOptimizerSettings(finalSettings);
        store.setShowOptimizerModal(false);

        const ops = calculateOptimizedPath(currentNestSheet, store.parts, store.tools, finalSettings);
        store.setOptimizedOperations(ops);
        store.setSimulationStep(0); 

        if (store.isGeneratingGCode) {
            const programNumber = store.activeSheetIndex + 1;
            const ncFilename = activeNest?.workOrder ? `${activeNest.workOrder}_${programNumber}.nc` : `Program_${programNumber}.nc`;
            const code = generateGCode(currentNestSheet, store.parts, store.tools, ncFilename, store.machineSettings, finalSettings, activeNest?.settings.clampPositions, programNumber, ops);
            store.setGeneratedGCode(code);
            store.setShowGCodeModal(true);
        } else {
            store.addToast(`Оптимизация завершена. ${ops.length} операций.`, "success");
        }
    };

    const downloadGCode = () => {
        const activeNest = store.getActiveNest();
        const blob = new Blob([store.generatedGCode], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = activeNest?.workOrder ? `${activeNest.workOrder}_${store.activeSheetIndex + 1}.nc` : `Program_${store.activeSheetIndex + 1}.nc`;
        document.body.appendChild(link); link.click(); document.body.removeChild(link); URL.revokeObjectURL(url);
    };

    const onAutoPunchApply = (s: AutoPunchSettings) => { 
        const activePart = store.getActivePart();
        if (!activePart) return;

        const p = generateContourPunches(activePart.geometry, store.tools, s, store.turretLayouts, store.teachCycles); 

        // Update part in store
        const newPunches = p.map(px => ({...px, id: generateId()}));
        const updatedPart = { ...activePart, punches: [...activePart.punches, ...newPunches] };

        store.setParts(parts => parts.map(pt => pt.id === updatedPart.id ? updatedPart : pt));

        store.setShowAutoPunchSettingsModal(false); 
        store.addToast(`Сгенерировано: ${p.length}`, "success"); 
    };

    const onSaveTeachCycle = (name: string, symmetry: any) => {
        const activePart = store.getActivePart();
        const geometry = store.getActivePartProcessedGeometry();
        if (!activePart || !geometry) return;

        const cycle = createTeachCycleFromSelection(name, symmetry, store.selectedSegmentIds, store.selectedTeachPunchIds, activePart, geometry);
        if (cycle) { 
            store.setTeachCycles(prev => [...prev, cycle]); 
            store.setTeachMode(false); 
        }
        store.setShowTeachSaveModal(false);
    };

    // Wrapper for File Import to update Store
    const { handleFileUpload } = useFileImport({ 
        tools: store.tools, 
        setMode: store.setMode, 
        setActivePart: (part) => {
            store.setParts(prev => [...prev.filter(p => p.id !== part.id), part]);
            store.setActivePartId(part.id);
        }, 
        addToast: store.addToast 
    });

    return {
        handleRunNesting,
        onRunOptimization,
        downloadGCode,
        onAutoPunchApply,
        onSaveTeachCycle,
        handleFileUpload
    };
};

/**
 * Finn-Power CAD/CAM Studio - UI ORCHESTRATOR
 * ОТВЕТСТВЕННОСТЬ: Главная композиция интерфейса. 
 */
import React from 'react';
import { AppMode, PlacedTool, Part, Tool } from '../types';
import { useStore } from '../store/useStore';
import { useAppLogic } from '../hooks/useAppLogic';
import { useConfirmation } from '../hooks/useConfirmation';
import { usePanAndZoom } from '../hooks/usePanAndZoom';
import { useEditorState } from '../hooks/useEditorState';
import { HeaderBar } from './layout/HeaderBar';
import { MainWorkspace } from './layout/MainWorkspace';
import { SecondaryViewManager } from './layout/SecondaryViewManager';
import { ModalRegistry } from './layout/ModalRegistry';
import { generateId } from '../utils/helpers';

export const AppUI: React.FC = () => {
    // 1. Store State & Setters
    const store = useStore();
    const { 
        mode, setMode, 
        tools, parts, scripts, nests, turretLayouts, machineSettings, optimizerSettings, teachCycles,
        activeSheetIndex, setActiveSheetIndex,
        selectedNestPartId, setSelectedNestPartId,
        isNestingProcessing, nestingProgress, nestingStatus,
        optimizedOperations, simulationStep, isSimulating, simulationSpeed,
        toasts, removeToast,
        setParts, setTools, setScripts, setTurretLayouts, setMachineSettings,
        setOptimizedOperations, setSimulationStep, setIsSimulating, setSimulationSpeed,
        setShowTeachSaveModal, setShowAutoPunchSettingsModal, setShowOptimizerModal, setShowGCodeModal,
        generatedGCode, isGeneratingGCode
    } = store;

    const activeNest = store.getActiveNest();

    // 2. Logic Handlers
    const logic = useAppLogic();
    const { confirm, confirmationState, closeConfirmation } = useConfirmation();
    const panZoom = usePanAndZoom({ x: 0, y: 0, width: 2500, height: 1250 }); // Default viewBox

    // 3. Editor Logic (with local handlers)
    const handleAddPunches = (newPunches: Omit<PlacedTool, 'id'>[]) => {
        const activePartId = store.activePartId;
        if (!activePartId) return;

        setParts(prev => prev.map(p => {
            if (p.id === activePartId) {
                const punchesToAdd = newPunches.map(np => ({ ...np, id: generateId() }));
                return { ...p, punches: [...p.punches, ...punchesToAdd] };
            }
            return p;
        }));
    };

    const editorState = useEditorState({ 
        tools, 
        onAddPunches: handleAddPunches 
    });

    // 4. Props Construction for Dumb Components
    const sidebarProps = {
        mode,
        parts,
        activePart: editorState.activePart,
        activePartId: store.activePartId,
        setActivePartId: store.setActivePartId,
        onDeletePart: (id: string) => setParts(prev => prev.filter(p => p.id !== id)),
        tools,
        activeNest,
        activeSheetIndex,
        setActiveSheetIndex,
        onFileUpload: logic.handleFileUpload,

        // Manual Punch Props
        manualPunchMode: editorState.manualPunchMode,
        setManualPunchMode: editorState.setManualPunchMode,
        selectedToolId: editorState.selectedToolId,
        setSelectedToolId: editorState.setSelectedToolId,
        selectedPunchId: editorState.selectedPunchId,
        setSelectedPunchId: editorState.setSelectedPunchId,
        onDeletePunch: (id: string | string[]) => {
            const ids = Array.isArray(id) ? id : [id];
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.filter(x => !ids.includes(x.id)) } 
                    : p
            ));
            editorState.setSelectedPunchId(null);
        },
        onUpdatePunch: (id: string, updates: Partial<PlacedTool>) => {
            setParts(prev => prev.map(p => 
                p.id === store.activePartId 
                    ? { ...p, punches: p.punches.map(x => x.id === id ? { ...x, ...updates } : x) } 
                    : p
            ));
        },
        onClearAllPunches: () => {
            confirm('Очистить все', 'Вы уверены, что хотите удалить все удары?', () => {
                setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, punches: [] } : p));
            });
        },
        punchOrientation: editorState.punchOrientation,
        setPunchOrientation: editorState.setPunchOrientation,
        onCyclePunchOrientation: () => editorState.setPunchOrientation((editorState.punchOrientation + 90) % 360),
        snapMode: editorState.snapMode,
        setSnapMode: editorState.setSnapMode,
        punchOffset: editorState.punchOffset,
        setPunchOffset: editorState.setPunchOffset,

        nibbleSettings: editorState.nibbleSettings,
        setNibbleSettings: editorState.setNibbleSettings,
        destructSettings: editorState.destructSettings,
        setDestructSettings: editorState.setDestructSettings,

        // Nesting Settings
        onUpdateNestingSettings: (s: any, sp: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, settings: s, scheduledParts: sp } : n)),
        onUpdateNestMetadata: (m: any) => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, ...m } : n)),

        // Actions
        onOpenTurretView: () => setMode(AppMode.TurretSetup),
        onSavePartAsScript: () => { /* Implement if needed or use header/secondary logic */ },
        onSavePartAsStatic: () => {
             const ap = editorState.activePart;
             if (ap && activeNest) {
                 const newPart = { ...ap, id: generateId(), name: `${ap.name}_copy` };
                 setParts(prev => [...prev, newPart]);
                 store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, scheduledParts: [...n.scheduledParts, { partId: newPart.id, quantity: 1, nesting: ap.nesting }] } : n));
                 store.addToast('Деталь сохранена в раскрой', 'success');
             }
        },
        onUpdateActivePart: (u: Partial<Part>) => setParts(prev => prev.map(p => p.id === store.activePartId ? { ...p, ...u } : p)),
        onClosePart: () => store.setActivePartId(null),

        // Teach Mode
        teachMode: editorState.teachMode,
        setTeachMode: editorState.setTeachMode,
        onSaveTeachCycle: () => setShowTeachSaveModal(true),
        teachCycles,
        onDeleteTeachCycle: (id: string) => store.setTeachCycles(prev => prev.filter(c => c.id !== id)),

        // Nesting Actions
        onRunNesting: logic.handleRunNesting,
        isNestingProcessing,
        nestingProgress,
        nestingStatus,
        onClearNest: () => confirm('Сброс раскроя', 'Удалить все результаты?', () => store.setNests(prev => prev.map(n => n.id === store.activeNestId ? { ...n, sheets: [] } : n))),
        selectedNestPartId,
        onMoveNestPart: (id: string, dx: number, dy: number) => {
            store.setNests(prev => prev.map(n => {
                if (n.id !== store.activeNestId) return n;
                const sheets = n.sheets.map((s, idx) => {
                    if (idx !== activeSheetIndex) return s;
                    return { ...s, placedParts: s.placedParts.map(pp => pp.id === id ? { ...pp, x: pp.x + dx, y: pp.y + dy } : pp) };
                });
                return { ...n, sheets };
            }));
        },
        onRotateNestPart: (id: string) => {
            store.setNests(prev => prev.map(n => {
                if (n.id !== store.activeNestId) return n;
                const sheets = n.sheets.map((s, idx) => {
                    if (idx !== activeSheetIndex) return s;
                    return { ...s, placedParts: s.placedParts.map(pp => pp.id === id ? { ...pp, rotation: (pp.rotation + 90) % 360 } : pp) };
                });
                return { ...n, sheets };
            }));
        },
    };

    const canvasProps = {
        mode,
        activePart: editorState.activePart,
        processedGeometry: editorState.activePartProcessedGeometry,
        activeNest,
        currentNestSheet: activeNest?.sheets[activeSheetIndex] || null,
        tools,
        parts,
        svgRef: panZoom.svgRef,
        viewBox: panZoom.viewBox,
        setViewBox: panZoom.setViewBox,
        isDragging: panZoom.isDragging,
        getPointFromEvent: panZoom.getPointFromEvent,
        panZoomHandlers: panZoom.panZoomHandlers,
        onOpenAutoPunchSettings: () => setShowAutoPunchSettingsModal(true),
        punchCreationStep: editorState.manualPunch.punchCreationStep,
        punchCreationPoints: editorState.manualPunch.punchCreationPoints,
        manualPunchMode: editorState.manualPunchMode,
        selectedToolId: editorState.selectedToolId,
        selectedPunchId: editorState.selectedPunchId,
        onSelectPunch: editorState.setSelectedPunchId,
        placementReference: 0 as any,
        placementSide: 0 as any,
        punchOrientation: editorState.punchOrientation,
        snapMode: editorState.snapMode,
        punchOffset: editorState.punchOffset,
        nibbleSettings: editorState.nibbleSettings,
        teachMode: editorState.teachMode,
        selectedSegmentIds: editorState.selectedSegmentIds,
        selectedTeachPunchIds: editorState.selectedTeachPunchIds,
        onTeachBulkSelect: (segs: number[], punches: string[], add: boolean) => {
            if (add) {
                editorState.setSelectedSegmentIds(prev => [...new Set([...prev, ...segs])]);
                editorState.setSelectedTeachPunchIds(prev => [...new Set([...prev, ...punches])]);
            } else {
                editorState.setSelectedSegmentIds(segs);
                editorState.setSelectedTeachPunchIds(punches);
            }
        },
        selectedNestPartId,
        onSelectNestPart: setSelectedNestPartId,
        onMoveNestPart: sidebarProps.onMoveNestPart,
        optimizedOperations,
        simulationStep,
        onCanvasClick: editorState.manualPunch.handleCanvasClick // Implicitly used by PartEditorCanvas logic or separate handler
    };

    const rightPanelProps = {
        tools,
        selectedToolId: editorState.selectedToolId,
        setSelectedToolId: editorState.setSelectedToolId,
        onOpenTurretView: () => setMode(AppMode.TurretSetup),
        activeNest,
        allParts: parts,
        simulationStep,
        totalSimulationSteps: optimizedOperations ? optimizedOperations.length : 0,
        isSimulating,
        simulationSpeed,
        onToggleSimulation: () => setIsSimulating(!isSimulating),
        onStopSimulation: () => { setIsSimulating(false); setSimulationStep(0); },
        onStepChange: setSimulationStep,
        onSpeedChange: setSimulationSpeed,
        optimizedOperations,
    };

    const isMainMode = mode === AppMode.PartEditor || mode === AppMode.Nesting;

    return (
        <div className="flex flex-col h-full font-sans relative overflow-hidden">
            <HeaderBar 
                onGenerateGCode={() => { store.setIsGeneratingGCode(true); setShowOptimizerModal(true); }} 
                onOptimizePath={() => { store.setIsGeneratingGCode(false); setShowOptimizerModal(true); }}
            />

            <div className="flex flex-1 overflow-hidden bg-gray-900">
                {isMainMode ? (
                    <MainWorkspace 
                        mode={mode}
                        sidebarProps={sidebarProps}
                        canvasProps={canvasProps}
                        rightPanelProps={rightPanelProps}
                        activeSheetIndex={activeSheetIndex}
                        setActiveSheetIndex={setActiveSheetIndex}
                    />
                ) : (
                    <SecondaryViewManager 
                        mode={mode}
                        data={{
                            partLibrary: { parts, tools },
                            scriptLibrary: { scripts, tools, parts },
                            toolLibrary: { tools },
                            turretSetup: { tools, layouts: turretLayouts },
                            machineSetup: { settings: machineSettings }
                        }}
                        handlers={{
                            partLibrary: { 
                                onLoadPart: (p: Part) => { setParts(prev => [...prev.filter(x => x.id !== p.id), p]); store.setActivePartId(p.id); setMode(AppMode.PartEditor); }, 
                                onDeletePart: sidebarProps.onDeletePart, 
                                onUpdatePart: (p: Part) => setParts(prev => prev.map(x => x.id === p.id ? p : x)) 
                            },
                            scriptLibrary: { 
                                onSaveScript: (s: any) => setScripts(prev => [...prev.filter(x => x.id !== s.id), s]), 
                                onDeleteScript: (id: string) => setScripts(prev => prev.filter(x => x.id !== id)), 
                                onCreatePart: (p: Part) => { setParts(prev => [...prev, p]); store.setActivePartId(p.id); setMode(AppMode.PartEditor); }, 
                                onBatchProcess: (pNew: any[], spNew: any[]) => {
                                    setParts(prev => [...prev, ...pNew]);
                                    if (activeNest) store.setNests(prev => prev.map(n => n.id === activeNest.id ? { ...n, scheduledParts: [...n.scheduledParts, ...spNew] } : n));
                                    store.addToast(`Добавлено ${pNew.length} деталей`, 'success');
                                }
                            },
                            toolLibrary: { 
                                onSaveTool: (t: Tool) => setTools(prev => [...prev.filter(x => x.id !== t.id), t]), 
                                onDeleteTool: (id: string) => setTools(prev => prev.filter(x => x.id !== id)) 
                            },
                            turretSetup: { setTools, setLayouts: setTurretLayouts },
                            machineSetup: { onUpdate: setMachineSettings }
                        }}
                    />
                )}
            </div>

            <ModalRegistry 
                ui={{
                    showAutoPunchSettingsModal: store.showAutoPunchSettingsModal, setShowAutoPunchSettingsModal,
                    showTeachSaveModal: store.showTeachSaveModal, setShowTeachSaveModal,
                    showOptimizerModal: store.showOptimizerModal, setShowOptimizerModal,
                    showGCodeModal: store.showGCodeModal, setShowGCodeModal,
                    toasts, removeToast,
                    generatedGCode,
                    onAutoPunchApply: logic.onAutoPunchApply,
                    downloadGCode: logic.downloadGCode
                }}
                confirmation={{ state: confirmationState, close: closeConfirmation }}
                data={{
                    turretLayouts,
                    optimizerSettings,
                    parts,
                    tools
                }}
                handlers={{
                    onSaveTeachCycle: logic.onSaveTeachCycle,
                    onRunOptimization: logic.onRunOptimization
                }}
                activeNest={activeNest}
                activeSheetIndex={activeSheetIndex}
            />
        </div>
    );
};
